/** Default profile used as a safety fallback for any suburb missing data. */
const FALLBACK: SuburbProfile = {
  vibe: "a Gold Coast suburb with its own character and pace",
  landmarks: ["the surrounding Gold Coast suburbs"],
  residents: "Gold Coast locals, families, and working professionals",
  lifestyle: "weekday work, weekend gym or beach trips, family time",
  bodyToll: "the usual mix of work-day lower back, screen neck and weekend-warrior knee strain",
  studioMin: 20,
  stretchAngle:
    "Wherever you live on the Gold Coast, the body responds to the same things — long days at desks, weekends pushed too hard, decades of small ignored aches. Assisted PNF stretching addresses all three more effectively than any solo routine.",
  ptAngle:
    "A coached, periodised program is the difference between random gym time and actual progress. Whether you train at the Wicked Bodz studio or online, the principles don't change.",
  faqLocation:
    "Most Gold Coast clients are within 30 minutes of the Wicked Bodz studio in Surfers Paradise, with mobile home visits available across the coast.",
};

export function getProfile(slug: string): SuburbProfile {
  return PROFILES[slug] ?? FALLBACK;
}

export function getNeighbors(slug: string): string[] {
  return NEIGHBORS[slug] ?? [];
}

export function studioDistanceLabel(min: number): string {
  if (min <= 1) return "right on the doorstep";
  if (min <= 8) return `a quick ${min}-minute drive`;
  if (min <= 15) return `about a ${min}-minute drive`;
  if (min <= 25) return `around ${min} minutes`;
  if (min <= 35) return `about a ${min}-minute drive from the studio`;
  return `roughly ${min} minutes from the studio (mobile visits recommended)`;
}
